def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    denominator = 1 + v2 / 100
    if denominator == 0:
        return None

    value = v1 / denominator

    return {
        "value": value,
        "trace": {
            "v1_2017_net_interest_income": v1,
            "v2_increase_rate_percent": v2,
            "denominator": denominator,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": "monetary"
            }
        }
    }
